head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > setNumber]<br/>숫자 또는 숫자 문자열에 천 단위 콤마(,) 를 삽입한 문자열을 반환합니다.",
    "validation" : [
        "number <String|Number:Y:-> 콤마를 삽입할 숫자 또는 숫자 문자열을 설정합니다.",
        "숫자 또는 숫자 문자열에 천 단위 콤마(,) 를 삽입한 문자열을 반환합니다.",
        "number 파라미터가 null, undefined, 또는 빈 문자열이면 undefined 를 반환합니다.",
        "소수점 이하 자릿수는 콤마 없이 그대로 유지됩니다.",
        "숫자가 아닌 문자열(예: \"abc\") 도 그대로 처리되므로 의도하지 않은 결과가 반환될 수 있습니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.setReturnValue = function (value) {
    wf_body_bottom.getObj("scwin").setReturnValue(value);
};



// target1 : 양의 정수
scwin.btn_setNumber1_onclick = function (e) {
    let result = WebSquare.util.setNumber(1234652);
    scwin.setReturnValue("return : " + result);
};

// target2 : 음수 + 소수점
scwin.btn_setNumber2_onclick = function (e) {
    let result = WebSquare.util.setNumber(-1234.56);
    scwin.setReturnValue("return : " + result);
};

// target3 : 부호 포함 문자열
scwin.btn_setNumber3_onclick = function (e) {
    let result = WebSquare.util.setNumber("+1234652");
    scwin.setReturnValue("return : " + result);
};

// target4 : null
scwin.btn_setNumber4_onclick = function (e) {
    let result = WebSquare.util.setNumber(null);
    scwin.setReturnValue("return : " + result);
};

// target5 : undefined
scwin.btn_setNumber5_onclick = function (e) {
    let result = WebSquare.util.setNumber(undefined);
    scwin.setReturnValue("return : " + result);
};

// target6 : 빈 문자열
scwin.btn_setNumber6_onclick = function (e) {
    let result = WebSquare.util.setNumber("");
    scwin.setReturnValue("return : " + result);
};

// target7 : 숫자가 아닌 문자열
scwin.btn_setNumber7_onclick = function (e) {
    let result = WebSquare.util.setNumber("abc");
    scwin.setReturnValue("return : " + result);
};

// target8 : 0
scwin.btn_setNumber8_onclick = function (e) {
    let result = WebSquare.util.setNumber(0);
    scwin.setReturnValue("return : " + result);
};

// target9 : 파라미터 입력값 사용
scwin.btn_setNumber9_onclick = function (e) {
    let paramValue = par_number.getValue();
    let result = WebSquare.util.setNumber(paramValue);
    scwin.setReturnValue("return : " + result);
};
